@{
    'mode-switch' = @{ Id='IPO-01'; Path='模式切换'; Input='地图编辑 ↔ 区域编辑连续切换 20 次'; Process=@('① 观察模式状态','② 检查工具栏','③ 检查 Pointer / Capture','④ 检查 Hover / Preview','⑤ 检查 DEM'); Output='状态一致，无残留、无异常丢失' }
    'region-editing' = @{ Id='IPO-02'; Path='区域编辑'; Input='创建、选择并拖动一个区域顶点'; Process=@('① 进入区域编辑','② 选择目标区域','③ 拖动顶点并观察预览','④ 松开后重新选择区域','⑤ 检查边界与名称'); Output='顶点位置、区域边界和名称一致' }
    'terrain-dem' = @{ Id='IPO-03'; Path='地形 / DEM'; Input='加载 DEM 后缩放、平移并切换地形相关视图'; Process=@('① 加载目标 DEM','② 观察地形高度与覆盖范围','③ 缩放和平移视图','④ 切换相关显示状态','⑤ 检查返回后数据仍在'); Output='地形连续可见，DEM 数据无丢失或异常跳变' }
    'vector-overlay' = @{ Id='IPO-04'; Path='地图矢量覆盖层'; Input='显示 Marker、Road、Region 三类覆盖层'; Process=@('① 打开地图视口','② 分别显示三类覆盖层','③ 缩放和平移观察几何','④ 检查标签与线条归属','⑤ 关闭再打开覆盖层'); Output='覆盖层位置、标签和显示状态与数据一致' }
    'inspector-editing' = @{ Id='IPO-05'; Path='Inspector 属性编辑'; Input='选中对象后编辑一个属性并切换到另一对象再返回'; Process=@('① 选中目标对象','② 修改指定属性','③ 提交修改并观察值','④ 切换到另一对象','⑤ 返回并检查原属性'); Output='提交对象、属性值和返回后的显示一致' }
    'workspace-selection' = @{ Id='IPO-06'; Path='工作区 / 模式选择'; Input='在管理、地图编辑和区域编辑工作区之间连续切换'; Process=@('① 观察当前工作区','② 选择下一个工作区','③ 检查选中态与禁用态','④ 检查邻接工具栏','⑤ 返回初始工作区'); Output='工作区状态和可用工具与当前上下文一致' }
}
